  [9483] = { "敵に大岩を投げつけ、Physicalダメージを与えます。", nil, 0x39cae954, nil, "um" },
  [9484] = { "アンデッドの敵を最大$D1の間拘束します。拘束された相手は移動も攻撃も呪文の詠唱もできません。ダメージを与えると拘束が解けます。一度に拘束できる対象は一体だけです。", "束縛されています。", 0xf52c43fa, 0xbae53c8d, "uu" },
  [9485] = { "対象のアンデッドの敵を最大$D1の間束縛します。束縛された対象は移動、攻撃、呪文の詠唱ができません。ダメージを与えると対象は解放されます。同時に束縛できる対象は1体だけです。", "束縛されています。", 0xf52c43fa, 0xbae53c8d, "uu" },
