  [9492] = { "持続的にダメージを与えるフィニッシュ技です。ダメージはコンボポイントごと、およびAttack Powerによって増加します：\n $N1ポイント：$D1かけて$N2のダメージ。\n $N4ポイント：$D2かけて$N5のダメージ。\n $N7ポイント：$D3かけて$N8のダメージ。\n $N10ポイント：$D4かけて$N11のダメージ。\n $N13ポイント：$D5かけて$N14のダメージ。", "$N2秒ごとに$N1の出血ダメージを受けます。", 0x49157ab0, 0x75c83da5, "uu" },
  [9493] = { "持続的にダメージを与えるフィニッシュ技です。ダメージはコンボポイントごと、およびAttack Powerによって増加します：\n $N1ポイント：$D1かけて$N2のダメージ。\n $N4ポイント：$D2かけて$N5のダメージ。\n $N7ポイント：$D3かけて$N8のダメージ。\n $N10ポイント：$D4かけて$N11のダメージ。\n $N13ポイント：$D5かけて$N14のダメージ。", "$N2秒ごとに$N1の出血ダメージを受けます。", 0x49157ab0, 0x75c83da5, "uu" },
