  [9573] = { "術者の前方の円錐範囲にいる敵に$N1のFireダメージを与えます。", nil, 0xad2ec576, nil, "um" },
  [9574] = { "敵に$N1のFireダメージを与え、$D1の間、その敵が受けるFireダメージを$N2増加させます。", "受けるFireダメージが$N1増加しています。", 0x03b94a10, 0xbe4d5ef3, "uu" },
  [9576] = { "$D1の間、術者を動けなくし、術者が与えるPhysicalダメージを$N1増加させます。", "移動できません。\n与える物理ダメージが$N1増加しています。", 0x6a05b4cc, 0xb69da191, "uu" },
  [9577] = { "Uldamanの地図の部屋に置いてください。", nil, 0xff5843e1, nil, "um" },
  [9578] = { "姿を薄れさせ、$D1の間、敵に攻撃されにくくします。Fade（Rank 1）より効果的です。", "脅威レベルが低下しています。", 0x3c676ea1, 0x904dd7ad, "uu" },
