  [9587] = { "$D1の間、術者が透明状態を見破れるようにし、術者を透明にします。ただしこの呪文は不安定で、早く切れることがあります。", "透明なものを見つけ、Invisibilityを付与します。", 0x666e0d07, 0x37a80466, "uu" },
