  [9632] = { "近くのすべての敵を攻撃し、$D2の間、$N2秒ごとに武器ダメージ＋$N1のダメージを与え、自分の移動速度を$N4%低下させます。", "周囲のすべての敵を攻撃しています。\n移動速度が$N1%低下しています。", 0x13eb78d9, 0xcd398f39, "uu" },
  [9634] = { "Dire Bear Formに変身し、Attack Powerが$N1、アイテムによるアーマーが$N2%、体力が$N3上昇します。また、術者をPolymorph効果から守り、さまざまな熊のアビリティを使えるようになります。\n\n変身することで、術者はPolymorphとMovement Impairingの効果から解放されます。", "Polymorph効果に対する免疫があります。Attack Powerが$N1、アイテムによるアーマーの上昇量が$N2%、体力が$N3増加しています。", 0x47ab4b64, 0x54e107c3, "uu" },
