  [9912] = { "対象に$N1のNatureダメージを与えます。", nil, 0xb57329ad, nil, "um" },
  [9913] = { "ドルイドが忍び歩きできるようになりますが、移動速度が$N1%低下します。解除するまで持続します。", "隠密状態です。移動速度が$N1%低下しています。", 0x17709e32, 0x2854da84, "uu" },
