  [9921] = { "1時間6で武器のダメージを増加させるには、鈍器のバランスをとります。レベル200以上の項目に適用することはできません。", nil, 0x77c8a0aa, nil, "um" },
  [9930] = { "パーティメンバーと共感の絆を結び、そのパーティメンバーが受けるすべてのダメージの$N1%を術者が肩代わりします。効果時間は$D1です。", "パーティーメンバー一人が受けるすべてのダメージの$N1%を分担しています。", 0x8318969b, 0x2c5cbd89, "uu" },
